-- #1211 (ADR-007) - product restrictions, explicit stock states, restriction audit log.
--
-- HAND-AUTHORED, not generated by `prisma migrate dev --create-only`: that command refuses on the
-- dev database ("The migration `20260820200500_p8_image_needs_review` was modified after it was
-- applied") and offers only `migrate reset`, which would drop every row - the open `#895`. The DDL
-- below was produced offline by `prisma migrate diff --from-schema-datamodel <staging schema>
-- --to-schema-datamodel prisma/schema.prisma --script`, so it touches no database and cannot
-- propose dropping the hand-authored `pg_trgm` indexes (`#508`). It is Prisma's own output with
-- exactly two deliberate edits, each marked below:
--
--   1. `Inventory.stockMode` is added with DEFAULT 'TRACKED' and the default is then changed to
--      'UNKNOWN'. Every row that exists today behaves as tracked (purchasable iff quantity > 0), so
--      it must keep doing so; every row created from now on without an explicit mode must fail
--      closed. Two DDL statements, no UPDATE, and the end state matches the schema's
--      @default(UNKNOWN).
--   2. CHECK "Product_restricted_inactive_check", which Prisma cannot model: a restricted product
--      is never active, whatever the application does.
--
-- Purely additive: four enums, two columns, one table, one index, three foreign keys, one CHECK.

-- CreateEnum
CREATE TYPE "ProductRestriction" AS ENUM ('PROHIBITED', 'AGE_RESTRICTED', 'NOT_DELIVERABLE', 'NEEDS_REVIEW');

-- CreateEnum
CREATE TYPE "StockMode" AS ENUM ('UNKNOWN', 'TRACKED', 'UNTRACKED');

-- CreateEnum
CREATE TYPE "ProductRestrictionAuditAction" AS ENUM ('RESTRICTION_SET', 'RESTRICTION_CLEARED');

-- CreateEnum
CREATE TYPE "ProductRestrictionChangeSource" AS ENUM ('PRODUCT_FORM', 'BULK_ACTION', 'IMPORT');

-- AlterTable
ALTER TABLE "Product" ADD COLUMN     "restriction" "ProductRestriction";

-- AlterTable (deliberate edit 1: existing rows become TRACKED, new rows default to UNKNOWN)
ALTER TABLE "Inventory" ADD COLUMN     "stockMode" "StockMode" NOT NULL DEFAULT 'TRACKED';
ALTER TABLE "Inventory" ALTER COLUMN "stockMode" SET DEFAULT 'UNKNOWN';

-- CreateTable
CREATE TABLE "ProductRestrictionAuditLog" (
    "id" TEXT NOT NULL,
    "vendorId" TEXT NOT NULL,
    "productId" TEXT NOT NULL,
    "action" "ProductRestrictionAuditAction" NOT NULL,
    "fromRestriction" "ProductRestriction",
    "toRestriction" "ProductRestriction",
    "actorUserId" TEXT,
    "source" "ProductRestrictionChangeSource" NOT NULL,
    "reason" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "ProductRestrictionAuditLog_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "ProductRestrictionAuditLog_vendorId_productId_createdAt_idx" ON "ProductRestrictionAuditLog"("vendorId", "productId", "createdAt");

-- AddForeignKey
ALTER TABLE "ProductRestrictionAuditLog" ADD CONSTRAINT "ProductRestrictionAuditLog_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "Vendor"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ProductRestrictionAuditLog" ADD CONSTRAINT "ProductRestrictionAuditLog_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ProductRestrictionAuditLog" ADD CONSTRAINT "ProductRestrictionAuditLog_actorUserId_fkey" FOREIGN KEY ("actorUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddCheckConstraint (deliberate edit 2: Prisma cannot model it)
ALTER TABLE "Product" ADD CONSTRAINT "Product_restricted_inactive_check" CHECK (NOT ("isActive" AND "restriction" IS NOT NULL));
